// Package regions contains the list of CoD server locations and their IP ranges.
//
// The file regions.json is generated by cmd/gen-regions from data/catalog.json and the
// official IP lists of the cloud providers. A copy is embedded in the app. The app can
// also download a newer copy and keep it in its data folder.
package regions

import (
	"context"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/netip"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Schema is the regions.json format version. The app ignores files with a different schema.
const Schema = 1

// DefaultUpdateURL is the online copy of regions.json. The weekly job updates it.
const DefaultUpdateURL = "https://raw.githubusercontent.com/1ukah/cod-server-picker/master/internal/regions/regions.json"

const cacheName = "regions.json"

//go:embed regions.json
var embedded []byte

type File struct {
	Schema    int       `json:"schema"`
	Generated time.Time `json:"generated"`
	Regions   []Region  `json:"regions"`
	Presets   []Preset  `json:"presets"`
}

type Region struct {
	ID        string     `json:"id"`
	Name      string     `json:"name"`
	Locations []Location `json:"locations"`
}

type Location struct {
	ID      string `json:"id"`
	Name    string `json:"name"`
	Country string `json:"country"`
	// Beacons are server IPs that the game was seen to contact at this location.
	Beacons []string `json:"beacons"`
	// PingIPs are the beacons that the ping test can use (ICMP). Google Cloud IPs are not
	// in this list: the Google network does not show its routers, so the result is wrong.
	PingIPs []string `json:"pingIps,omitempty"`
	// PingURLs are HTTPS test endpoints in the same Google Cloud regions (gcping.com).
	PingURLs []string `json:"pingUrls,omitempty"`
	// Providers are the cloud provider regions that contain the beacons, for example "gcp:us-east4".
	Providers []string `json:"providers,omitempty"`
	// Ranges are all the IP ranges of those provider regions. These are blocked.
	Ranges []string `json:"ranges,omitempty"`
}

// Preset allows the listed regions and blocks all other regions.
type Preset struct {
	ID    string   `json:"id"`
	Name  string   `json:"name"`
	Allow []string `json:"allow"`
}

// Source tells where the loaded file came from.
type Source string

const (
	SourceEmbedded Source = "built-in"
	SourceCache    Source = "downloaded"
)

// Parse decodes and validates a regions.json file.
func Parse(data []byte) (*File, error) {
	var f File
	if err := json.Unmarshal(data, &f); err != nil {
		return nil, err
	}
	if err := f.Validate(); err != nil {
		return nil, err
	}
	return &f, nil
}

// Validate checks that the file is usable by this version of the app.
func (f *File) Validate() error {
	if f.Schema != Schema {
		return fmt.Errorf("regions schema %d is not supported (want %d)", f.Schema, Schema)
	}
	if len(f.Regions) == 0 {
		return errors.New("regions file has no regions")
	}
	seen := map[string]bool{}
	for _, r := range f.Regions {
		if r.ID == "" || seen[r.ID] {
			return fmt.Errorf("bad or duplicate region id %q", r.ID)
		}
		seen[r.ID] = true
		for _, l := range r.Locations {
			if l.ID == "" || seen[l.ID] {
				return fmt.Errorf("bad or duplicate location id %q", l.ID)
			}
			seen[l.ID] = true
			if len(l.Ranges) == 0 {
				return fmt.Errorf("location %q has no ranges", l.ID)
			}
			for _, u := range l.PingURLs {
				if !strings.HasPrefix(u, "https://") {
					return fmt.Errorf("location %q: bad ping URL %q", l.ID, u)
				}
			}
			for _, s := range l.Ranges {
				if _, err := netip.ParsePrefix(s); err != nil {
					return fmt.Errorf("location %q: bad range %q", l.ID, s)
				}
			}
		}
	}
	for _, p := range f.Presets {
		for _, id := range p.Allow {
			if f.Region(id) == nil {
				return fmt.Errorf("preset %q: unknown region %q", p.ID, id)
			}
		}
	}
	return nil
}

// Embedded returns the copy of regions.json that is built into the app.
func Embedded() (*File, error) {
	return Parse(embedded)
}

// Load returns the newest valid file: the downloaded copy in dataDir or the built-in copy.
func Load(dataDir string) (*File, Source, error) {
	builtIn, err := Embedded()
	if err != nil {
		return nil, "", fmt.Errorf("built-in regions: %w", err)
	}
	if dataDir == "" {
		return builtIn, SourceEmbedded, nil
	}
	data, err := os.ReadFile(filepath.Join(dataDir, cacheName))
	if err != nil {
		return builtIn, SourceEmbedded, nil
	}
	cached, err := Parse(data)
	if err != nil || !cached.Generated.After(builtIn.Generated) {
		return builtIn, SourceEmbedded, nil
	}
	return cached, SourceCache, nil
}

// Update downloads regions.json from url. If the download is newer than current and valid,
// Update saves it in dataDir and returns it with updated set to true.
// On any problem, Update returns current and an error. The caller can ignore the error.
func Update(ctx context.Context, url, dataDir string, current *File) (f *File, updated bool, err error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return current, false, err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return current, false, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return current, false, fmt.Errorf("download regions: HTTP %d", resp.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, 32<<20))
	if err != nil {
		return current, false, err
	}
	next, err := Parse(data)
	if err != nil {
		return current, false, fmt.Errorf("downloaded regions: %w", err)
	}
	if current != nil && !next.Generated.After(current.Generated) {
		return current, false, nil
	}
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		return current, false, err
	}
	tmp := filepath.Join(dataDir, cacheName+".tmp")
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return current, false, err
	}
	if err := os.Rename(tmp, filepath.Join(dataDir, cacheName)); err != nil {
		return current, false, err
	}
	return next, true, nil
}

func (f *File) Region(id string) *Region {
	for i := range f.Regions {
		if f.Regions[i].ID == id {
			return &f.Regions[i]
		}
	}
	return nil
}

func (f *File) Location(id string) *Location {
	for i := range f.Regions {
		for j := range f.Regions[i].Locations {
			if f.Regions[i].Locations[j].ID == id {
				return &f.Regions[i].Locations[j]
			}
		}
	}
	return nil
}

// RegionOf returns the region that contains the location.
func (f *File) RegionOf(locationID string) *Region {
	for i := range f.Regions {
		for _, l := range f.Regions[i].Locations {
			if l.ID == locationID {
				return &f.Regions[i]
			}
		}
	}
	return nil
}

// AllLocationIDs returns every location ID in display order.
func (f *File) AllLocationIDs() []string {
	var ids []string
	for _, r := range f.Regions {
		for _, l := range r.Locations {
			ids = append(ids, l.ID)
		}
	}
	return ids
}

// LocationIDs returns the location IDs of one region.
func (r *Region) LocationIDs() []string {
	ids := make([]string, len(r.Locations))
	for i, l := range r.Locations {
		ids[i] = l.ID
	}
	return ids
}

// Preset returns the preset with the given ID.
func (f *File) Preset(id string) *Preset {
	for i := range f.Presets {
		if f.Presets[i].ID == id {
			return &f.Presets[i]
		}
	}
	return nil
}

// BlockedBy returns the location IDs that a preset blocks: all locations outside the allowed regions.
func (f *File) BlockedBy(p *Preset) []string {
	allow := map[string]bool{}
	for _, id := range p.Allow {
		allow[id] = true
	}
	var ids []string
	for _, r := range f.Regions {
		if allow[r.ID] {
			continue
		}
		for _, l := range r.Locations {
			ids = append(ids, l.ID)
		}
	}
	return ids
}

// Find returns the location whose ranges contain ip, or nil.
func (f *File) Find(ip netip.Addr) *Location {
	for i := range f.Regions {
		for j := range f.Regions[i].Locations {
			l := &f.Regions[i].Locations[j]
			for _, s := range l.Ranges {
				if p, err := netip.ParsePrefix(s); err == nil && p.Contains(ip) {
					return l
				}
			}
		}
	}
	return nil
}
